#include <iostream>
#include <string>

struct Device {
    std::string deviceName;
    std::string deviceType;
    bool isHardwareRunning;
};

void runSoftwareCommand(Device& dev, const std::string& command) {
    std::cout << "Executing software command '" << command 
              << "' on hardware: " << dev.deviceName 
              << " (" << dev.deviceType << ")\n";
    dev.isHardwareRunning = true;
}

int main() {
    Device mobile{"Smartphone", "Handheld", false};
    Device desktop{"Workstation", "General-Purpose Computer", false};

    runSoftwareCommand(mobile, "Sync Mobile Health Data");
    runSoftwareCommand(desktop, "Analyze DNA Sequence");

    return 0;
}

#include <iostream>
#include <string>
#include <vector>

struct ResearchWorkunit {
    std::string projectName;
    int basePairsProcessed;
};

struct CloudServerResource {
    std::string serviceName;
    int allocatedCapacityGB;
};

int main() {
    // Simulating World Community Grid volunteer data processing
    std::vector<ResearchWorkunit> gridUnits = {
        {"Human Genome Analysis", 500000},
        {"Clean Water Simulation", 120000}
    };

    // Simulating Cloud Computing dynamic resource scaling
    std::vector<CloudServerResource> cloudServices = {
        {"Electronic Health Records DB", 1024},
        {"AMBER Alert Dispatch Server", 256}
    };

    std::cout << "--- World Community Grid Volunteer Processing ---\n";
    for (const auto& unit : gridUnits) {
        std::cout << "Project: " << unit.projectName 
                  << " | Processed: " << unit.basePairsProcessed << " units\n";
    }

    std::cout << "\n--- Cloud Computing On-Demand Resources ---\n";
    for (const auto& svc : cloudServices) {
        std::cout << "Service: " << svc.serviceName 
                  << " | Allocated Storage: " << svc.allocatedCapacityGB << " GB\n";
    }

    return 0;
}

#include <iostream>
